/**
 * 3D CAD parameter contract for the web viewer.
 *
 * Mirrors osdagbridge.core.bridge_types.plate_girder.dto.BridgeParametersDTO
 * and the model_data generated by PlateGirderCADGenerator (cad_generator.py).
 * All dimensions are in millimetres and angles in degrees unless noted.
 */

export interface GirderSectionDims {
  /** Girder total depth (mm). */
  d: number;
  /** Top flange width (mm). */
  bf: number;
  /** Bottom flange width (mm). */
  bf_b: number;
  /** Top flange thickness (mm). */
  tf: number;
  /** Bottom flange thickness (mm). */
  tf_b: number;
  /** Web thickness (mm). */
  tw: number;
}

export interface GirderSegment {
  length: number;
  D: number;
  tw: number;
  T_ft: number;
  T_fb: number;
  B_ft: number;
  B_fb: number;
}

export interface ShearStudParams {
  base_diameter: number;
  top_diameter: number;
  base_height: number;
  top_height: number;
  num_per_section: number;
  transverse_spacing: number;
  pitch: number;
}

export interface SectionDimsDTO {
  leg_h: number;
  leg_w: number;
  connection_type?: string;
  depth?: number;
  flange_width?: number;
  web_thickness?: number;
  flange_thickness?: number;
}

export interface GrillageNodeData {
  id: number;
  x: number; // longitudinal (m)
  y: number; // transverse (m)
  z: number; // elevation (m)
  label: string;
}

export interface GrillageMemberData {
  id: number;
  node1: number;
  node2: number;
  type?: 'longitudinal' | 'transverse' | 'bracing';
}

export type FootpathConfig = 'NONE' | 'LEFT' | 'RIGHT' | 'BOTH';

export interface BridgeCadParameters {
  /** Span length L (mm). */
  span_length: number;
  /** Number of longitudinal girders. */
  num_girders: number;
  /** Centre-to-centre girder spacing (mm). */
  girder_spacing: number;
  /** Skew angle in degrees (0 = straight). */
  skew_angle: number;

  /** Carriageway width (mm). */
  carriageway_width: number;
  /** Deck slab thickness (mm). */
  deck_thickness: number;
  /** Deck overhang from outermost girder to deck edge (mm). */
  deck_overhang: number;

  footpath_config: FootpathConfig;
  /** Footpath width (mm). */
  footpath_width: number;
  /** Footpath slab thickness (mm). */
  footpath_thickness: number;

  /** Railing type key (e.g. "IRC 5 - RCC Railing", "IRC 5 - Steel Railing"). */
  railing_type: string;
  /** Railing width (mm). */
  railing_width: number;
  /** Number of horizontal rails (steel railing). */
  rail_count: number;

  /** Crash barrier type key (e.g. "Rigid", "Semi-Rigid"). */
  barrier_type: string;
  /** Crash barrier subtype (e.g. "IRC-5R", "Single W-beam", "Double W-beam"). */
  crash_barrier_subtype: string;
  /** Crash barrier base/kerb width (mm). */
  crash_barrier_width: number;

  median_enabled: boolean;
  /** Median type key (e.g. "Raised Kerb", "RCC Crash Barrier", "Metallic Crash Barrier"). */
  median_type: string;

  /** Wearing course / surfacing thickness (mm). */
  wearing_course_thickness: number;

  /** Girder section dimensions (mm). */
  girder: GirderSectionDims;
  /** Optional girder segments for variable depth / flange sizing. */
  girder_segments?: GirderSegment[];

  // Intermediate Stiffeners
  include_intermediate_stiffeners: boolean;
  intermediate_stiffener_spacing: number;
  intermediate_stiffener_thickness: number;
  intermediate_stiffener_outstand?: number;

  // Bearing / End Stiffeners
  num_end_stiffener_pairs: number;
  end_stiffener_thickness: number;
  end_stiffener_outstand?: number;

  // Longitudinal Stiffeners
  include_longitudinal_stiffeners: boolean;
  num_longitudinal_stiffeners: number;
  longitudinal_stiffener_thickness: number;
  longitudinal_stiffener_outstand?: number;

  // Shear Studs
  shear_stud_params: ShearStudParams;

  // Cross Bracing System
  cross_bracing_spacing: number;
  bracing_type: 'X' | 'K';
  x_bracket_option?: 'BOTH' | 'TOP' | 'BOTTOM' | 'NONE';
  k_top_bracket?: boolean;

  diagonal_section_type: string;
  diagonal_section_dims: SectionDimsDTO;
  diagonal_thickness: number;

  top_chord_section_type: string;
  top_chord_section_dims: SectionDimsDTO;
  top_chord_thickness: number;

  bottom_chord_section_type: string;
  bottom_chord_section_dims: SectionDimsDTO;
  bottom_chord_thickness: number;

  // End Diaphragm
  end_diaphragm_type: string;
  end_diaphragm_bracing_type: string;

  // Material grades
  steel_grade: string;
  concrete_grade: string;

  // Grillage model overlays (nodes & elements)
  nodes?: Record<number, GrillageNodeData>;
  members?: Record<number, GrillageMemberData>;
}
